sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float2 center;
uniform float startAngle;
uniform float clockwise;
uniform float feather;
uniform float mode;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 d = coord - center * size;
    float t = fract((atan(d.y, d.x) - radians(startAngle)) / 6.2831853 + 1.0);
    if (clockwise < 0.5) t = 1.0 - t;
    float edgePos = progress * (1.0 + feather) - feather;
    float reveal = 1.0 - smoothstep(edgePos, edgePos + max(feather, 0.001), t);
    float mask = mode < 0.5 ? reveal : 1.0 - reveal;
    return fin(c, c * mask, opacity);
}
